// What a list shows when it has nothing in it: a title, a sentence, and usually a next step.
import type { ReactNode } from "react";
import styles from "./EmptyState.module.css";

interface EmptyStateProps {
  title: string;
  children?: ReactNode;
  action?: ReactNode;
}

export function EmptyState({ title, children, action }: EmptyStateProps) {
  return (
    <div data-ui="empty-state" className={styles.emptyState}>
      <h2 className={styles.title}>{title}</h2>
      {children && <p className={styles.text}>{children}</p>}
      {action}
    </div>
  );
}

// The entry point. It loads the global styles, registers what happens when a session expires,
// and renders the providers around the router inside <StrictMode>, which in development renders
// twice and runs effects twice to surface impure code and missing cleanups. The root's error
// options log errors that error boundaries caught and the ones they didn't.
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { RouterProvider } from "react-router/dom";
import { AppProviders } from "@/app/providers";
import { queryClient } from "@/app/query-client";
import { router } from "@/app/router";
import { redirectOnExpiredSession } from "@/features/auth";
import "@/styles/tokens.css";
import "@/styles/global.css";

redirectOnExpiredSession(queryClient, (to) => router.navigate(to));

createRoot(document.getElementById("root")!, {
  onCaughtError: (error, info) => console.warn("An error boundary caught:", error, info.componentStack),
  onUncaughtError: (error, info) => console.error("Uncaught error:", error, info.componentStack),
}).render(
  <StrictMode>
    <AppProviders queryClient={queryClient}>
      <RouterProvider router={router} />
    </AppProviders>
  </StrictMode>,
);

// A small colored label for a priority, a status, or a task label. A tone picks a theme color; a
// color (a label's own #rrggbb) overrides it through a CSS variable.
import { clsx } from "clsx";
import type { CSSProperties, ReactNode } from "react";
import styles from "./Tag.module.css";

export type TagTone = "neutral" | "info" | "success" | "warning" | "danger";

interface TagProps {
  tone?: TagTone;
  color?: string;
  children: ReactNode;
}

export function Tag({ tone = "neutral", color, children }: TagProps) {
  const style = color ? ({ "--tag-color": color } as CSSProperties) : undefined;
  return (
    <span data-ui="tag" className={clsx(styles.tag, styles[tone], color && styles.custom)} style={style}>
      {children}
    </span>
  );
}

